create table public.secondary_staff_salary_structures(id uuid primary key default gen_random_uuid(),school_id uuid not null references public.schools(id) on delete cascade,name text not null,grade text,base_salary numeric(12,2) not null default 0 check(base_salary>=0),default_allowances numeric(12,2) not null default 0 check(default_allowances>=0),currency text not null default 'MWK',is_active boolean not null default true,created_at timestamptz not null default now(),created_by uuid not null references auth.users(id),unique(school_id,name));
alter table public.secondary_staff_salary_structures enable row level security;
alter table public.secondary_staff_salary_structures force row level security;
grant select,insert,update,delete on public.secondary_staff_salary_structures to authenticated;
create policy secondary_staff_salary_structures_read on public.secondary_staff_salary_structures for select to authenticated using(exists(select 1 from public.school_memberships m where m.school_id=secondary_staff_salary_structures.school_id and m.user_id=(select auth.uid()) and m.is_active and m.role in('owner','school_admin','headteacher','bursar')));
create policy secondary_staff_salary_structures_insert on public.secondary_staff_salary_structures for insert to authenticated with check(created_by=(select auth.uid()) and exists(select 1 from public.school_memberships m where m.school_id=secondary_staff_salary_structures.school_id and m.user_id=(select auth.uid()) and m.is_active and m.role in('owner','school_admin','bursar')));
create policy secondary_staff_salary_structures_update on public.secondary_staff_salary_structures for update to authenticated using(exists(select 1 from public.school_memberships m where m.school_id=secondary_staff_salary_structures.school_id and m.user_id=(select auth.uid()) and m.is_active and m.role in('owner','school_admin','bursar'))) with check(exists(select 1 from public.school_memberships m where m.school_id=secondary_staff_salary_structures.school_id and m.user_id=(select auth.uid()) and m.is_active and m.role in('owner','school_admin','bursar')));
create policy secondary_staff_salary_structures_delete on public.secondary_staff_salary_structures for delete to authenticated using(exists(select 1 from public.school_memberships m where m.school_id=secondary_staff_salary_structures.school_id and m.user_id=(select auth.uid()) and m.is_active and m.role in('owner','school_admin')));
